"""Build a self-contained HTML result report from recorded validation evidence."""
from pathlib import Path
import base64
import collections
import html
import json
import re
import sys

sys.stdout.reconfigure(encoding='utf-8',errors='replace')

root=Path(__file__).resolve().parents[1]
out=root/'output'
report=out/'report'
report.mkdir(exist_ok=True)
def read(name):return json.loads((out/name).read_text(encoding='utf-8'))
def cli_result(name):
    content=(out/name).read_text(encoding='utf-8-sig')
    return json.loads(content.split('### Result',1)[1].split('### Ran Playwright code',1)[0].strip())
def esc(value):return html.escape(str(value))
def image(name):return 'data:image/png;base64,'+base64.b64encode((out/name).read_bytes()).decode('ascii')

samples=json.loads((root/'data/validation/samples.json').read_text(encoding='utf-8'))
fixture_manifest=json.loads((root/'data/validation/fixtures.json').read_text(encoding='utf-8'))
sample_map={x['id']:x for x in samples['samples']+fixture_manifest['samples']}
batch=read('ui-batch-results.json')
recovery=cli_result('ui-recovery-final.log')+cli_result('ui-fixture-recovery.log')
failure=cli_result('ui-save-failure-final.log')
exports=read('independent-export-checks.json')
integrity=read('source-integrity.json')
unit_text=(out/'all-tests-final.log').read_text(encoding='utf-8-sig')
unit_total=int(re.search(r'ℹ tests (\d+)',unit_text).group(1))
unit_pass=int(re.search(r'ℹ pass (\d+)',unit_text).group(1))
annotations=sum(len(x['annotationChecks']) for x in exports['results'])
pdfium_pages=sum(len(x['pdfiumPages']) for x in exports['results'])
all_passed=all(x['status']=='passed' for x in batch+recovery+exports['results']) and failure['passed'] and unit_total==unit_pass and integrity['checked']==integrity['unchanged']
if not all_passed:raise RuntimeError('Evidence contains a failure; do not generate a passing report')
summary={'decision':'phase-1 core acceptance passed within documented scope','sampleDocuments':len(batch),'samplePages':sum(x['pages'] for x in samples['samples']),
 'coreRenderedPages':sum(len(x['renderedPages']) for x in batch),'derivedPositiveFixtures':3,'exportedDocuments':len(exports['results']),
 'verifiedAnnotations':annotations,'restartDocuments':len(recovery),'restartAnnotations':sum(x['annotationCount'] for x in recovery),
 'pdfiumCheckedPages':pdfium_pages,'popplerCheckedFirstPages':len(exports['results']),'unitTests':unit_pass,'originalFilesUnchanged':integrity['unchanged'],
 'saveFailureRetryPassed':failure['passed'],'externalReader':'Microsoft Edge built-in PDF reader; Chinese popup visually verified',
 'limitations':['Password unlock/export not implemented','No OCR for scanned files','Existing embedded annotations are read-only','Not all 695 pages visually reviewed','Not a packaged desktop release','Word/WPS citation connector is a defined future boundary only']}
(out/'phase-1-summary.json').write_text(json.dumps(summary,ensure_ascii=False,indent=2),encoding='utf-8')
recovered={x['sampleKey']:x for x in recovery}
rows=[]
for item in exports['results']:
    key=item['sampleKey'];meta=sample_map[key]
    relative=Path(item['exportPath']).relative_to(root).as_posix()
    rows.append(f'<tr data-name="{esc(key+meta["originalName"])}"><td><code>{esc(key)}</code></td><td>{esc(meta["originalName"])}</td><td>{meta["pages"]}</td><td>{len(item["annotationChecks"])}</td><td><span class="pass">通过</span></td><td><a href="../../{esc(relative)}">打开导出 PDF ↗</a></td></tr>')
engine=exports['engines']
template='''<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>第一阶段技术验证结果 · 本地文献工作台</title><link rel="icon" href="data:,"><style>
:root{--bg:#f3f4ee;--paper:#fffefa;--ink:#233b30;--green:#255d41;--muted:#6e7d67;--line:#d8e0cf;--soft:#e7efe1;--amber:#86612d}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font:15px/1.85 "Segoe UI","Microsoft YaHei",sans-serif}a{color:var(--green);text-underline-offset:4px}h1,h2,h3,p{margin:0}h1{font-size:46px;line-height:1.3;letter-spacing:-1px}h2{font-size:27px;line-height:1.45;margin-bottom:16px}h3{font-size:17px}p+p{margin-top:12px}.page{max-width:1200px;margin:auto;padding:0 42px}header{padding:25px 0;border-bottom:1px solid var(--line);display:flex;justify-content:space-between;gap:20px;align-items:center;font-size:12px;color:var(--muted)}button{font:inherit;font-size:12px;padding:8px 15px;border:1px solid var(--line);border-radius:7px;background:var(--paper);color:var(--green);cursor:pointer}.hero{padding:55px 0 30px}.eyebrow{font:11px Consolas,monospace;letter-spacing:2px;color:var(--green);margin-bottom:18px}.hero h1 span{color:var(--green)}.lead{font-size:18px;max-width:940px;margin-top:24px}.scope{font-size:13px;color:var(--muted);max-width:960px;margin-top:16px}.badge{display:inline-block;padding:4px 10px;background:var(--soft);color:var(--green);font-size:12px;border-radius:5px;white-space:nowrap}.metrics{display:grid;grid-template-columns:repeat(4,1fr);gap:14px;margin:18px 0 30px}.metric{padding:23px;border:1px solid var(--line);border-radius:13px;background:var(--paper)}.metric strong{font:34px/1.3 Consolas,monospace;color:var(--green);display:block}.metric span{display:block;font-size:13px;margin-top:9px}.metric small{font-size:11px;color:var(--muted)}nav{display:flex;gap:20px;flex-wrap:wrap;padding:19px 0;border-top:1px solid var(--line);border-bottom:1px solid var(--line);font-size:13px}nav a{text-decoration:none}section{padding:42px 0;border-bottom:1px solid var(--line);scroll-margin-top:20px}.intro{color:var(--muted);margin-bottom:23px}.grid{display:grid;grid-template-columns:1fr 1fr;gap:20px}.card{padding:25px;border:1px solid var(--line);border-radius:13px;background:var(--paper)}.card p{font-size:14px;color:var(--muted);margin-top:11px}.card ul{padding-left:20px;font-size:14px;margin:12px 0 0}.card li+li{margin-top:9px}.flow{display:flex;gap:9px;align-items:center;margin-top:20px}.flow div{padding:16px 12px;flex:1;background:var(--soft);border-radius:9px;text-align:center;font-size:13px}.flow small{display:block;font-size:10px;color:var(--muted)}.flow b{color:#89a178;font-weight:400}.proof{margin:24px 0 0;border:1px solid var(--line);border-radius:13px;overflow:hidden;background:var(--paper)}.proof img{display:block;width:100%;height:auto}.proof figcaption{padding:14px 20px;font-size:12px;color:var(--muted)}.checklist{display:grid;grid-template-columns:repeat(3,1fr);gap:15px}.check{background:var(--paper);padding:21px;border:1px solid var(--line);border-radius:11px}.check strong{display:block;font-size:15px}.check p{font-size:13px;color:var(--muted);margin-top:9px}.check .pass{font-size:11px;margin-bottom:11px;display:inline-block}.pass{color:var(--green);font-weight:600}.note{margin-top:23px;border-left:3px solid #a98b4b;padding:17px 20px;background:#f5eddb;color:#7b6033;font-size:13px}.fixes{counter-reset:fix}.fix{counter-increment:fix;display:grid;grid-template-columns:36px 1fr;gap:14px;padding:20px 0;border-top:1px solid var(--line)}.fix:before{content:counter(fix,decimal-leading-zero);font:16px Consolas,monospace;color:#8d9d80;padding-top:3px}.fix h3{font-size:16px}.fix p{font-size:14px;color:var(--muted);margin-top:8px}.architecture{background:var(--soft);padding:24px;border-radius:12px;display:grid;grid-template-columns:repeat(3,1fr);gap:16px}.architecture div{background:var(--paper);padding:22px;border-radius:9px}.architecture h3{font-size:16px}.architecture p{font-size:13px;color:var(--muted);margin-top:10px}.code-tree{padding:20px 23px;background:#e9eee2;color:#516748;border-radius:10px;font:12px/1.95 Consolas,"Microsoft YaHei",monospace;white-space:pre-wrap;overflow-wrap:anywhere}.table-tools{display:flex;justify-content:space-between;align-items:center;gap:15px;flex-wrap:wrap;margin:20px 0 12px}input{padding:10px 12px;border:1px solid var(--line);border-radius:7px;background:var(--paper);font:13px "Microsoft YaHei",sans-serif;min-width:240px}.table-wrap{overflow:auto;border:1px solid var(--line);border-radius:11px;background:var(--paper)}table{width:100%;border-collapse:collapse;font-size:12px;text-align:left;min-width:780px}th{padding:14px 12px;background:#e8eee1;color:#52694a}td{padding:13px 12px;border-top:1px solid var(--line);vertical-align:top}td:nth-child(2){max-width:440px;overflow-wrap:anywhere}td:last-child{white-space:nowrap}td code{font-size:11px}details{border-top:1px solid var(--line);padding:17px 0}summary{cursor:pointer;font-weight:600;font-size:14px}details p{margin-top:10px;font-size:13px;color:var(--muted)}.links{display:grid;grid-template-columns:repeat(2,1fr);gap:12px;margin-top:20px}.links a{padding:13px 16px;border:1px solid var(--line);border-radius:8px;background:var(--paper);text-decoration:none;font-size:13px}.foot{padding:26px 0 40px;font-size:12px;color:var(--muted)}.small{font-size:12px;color:var(--muted)}.pill{display:inline-block;background:#f3ead6;color:#89652e;font-size:11px;padding:3px 8px;border-radius:5px;margin-bottom:12px}button:focus-visible,input:focus-visible,a:focus-visible,summary:focus-visible{outline:3px solid #b58f45;outline-offset:3px}html{scroll-behavior:smooth}[hidden]{display:none!important}@media(max-width:800px){.page{padding:0 20px}h1{font-size:34px}.metrics{grid-template-columns:1fr 1fr}.grid,.architecture{grid-template-columns:1fr}.checklist{grid-template-columns:1fr 1fr}.flow{flex-direction:column}.flow div{width:100%}.flow b{transform:rotate(90deg)}.links{grid-template-columns:1fr}.hero{padding-top:35px}.lead{font-size:16px}h2{font-size:24px}.metric{padding:19px}.metric strong{font-size:29px}section{padding:32px 0}}@media(max-width:430px){.checklist{grid-template-columns:1fr}.metrics{gap:10px}.metric{padding:16px}.metric span{font-size:12px}nav{gap:14px}header{font-size:10px}.lead{font-size:15px}}@media print{@page{size:A4;margin:14mm}body{background:white;font-size:10pt;print-color-adjust:exact;-webkit-print-color-adjust:exact}.page{max-width:none;padding:0}button,nav,input,.table-tools{display:none}.hero{padding:25px 0}h1{font-size:27pt}h2{font-size:19pt}.lead{font-size:12pt}.metrics{gap:10px}.metric{padding:15px}.metric strong{font-size:23pt}.metric span{font-size:10pt}section{padding:25px 0}.card,.check,.proof,.fix,.architecture{break-inside:avoid}.proof img{max-height:500px;object-fit:contain}.table-wrap{overflow:visible}table{min-width:0;font-size:8pt}th,td{padding:8px}tr{break-inside:avoid}.checklist{grid-template-columns:repeat(3,1fr)}details p{display:block!important}details::details-content{content-visibility:visible!important}h2,h3{break-after:avoid}.note{font-size:9pt}.links{display:none}.small,.foot{font-size:8pt}}
</style></head><body><main class="page"><header><span>本地文献工作台 / 第一阶段技术验证</span><div><span class="badge">2026.10.30 · 实测报告</span> <button id="print">打印报告</button></div></header>
<div class="hero"><div class="eyebrow">PHASE 01 / ENGINEERING VALIDATION</div><h1>阅读、保存、恢复、导出。<br><span>核心链路已通过验证。</span></h1><p class="lead">“成熟阅读器组件 + 专用文献管理界面”路线具备继续开发的基础。过程中发现并修复了初始化、阅读位置、图像解码和已有标注显示问题，再完成独立回归。</p><p class="scope">本次交付的是可运行的本地技术验证台与可继续开发的分层工程。它在本机浏览器运行，尚不是最终桌面安装版。以下结论只适用于列明的样本、操作与版本，不等于已经覆盖所有 PDF 或全部阅读器功能。</p></div>
<div class="metrics"><div class="metric"><strong>30 / 30</strong><span>现有论文副本通过核心流程</span><small>695 页文档，抽样渲染 90 页</small></div><div class="metric"><strong>101 / 101</strong><span>新标注保存、恢复与导出核对</span><small>含 3 类派生边界样本</small></div><div class="metric"><strong>33 / 33</strong><span>导出文件通过独立检查</span><small>PDFium + Poppler + pypdf</small></div><div class="metric"><strong>65 / 65</strong><span>原始 PDF 校验值未变</span><small>所有测试操作均使用副本</small></div></div>
<nav><a href="#results">验证结果</a><a href="#evidence">真实界面与外部查看</a><a href="#fixes">发现与修复</a><a href="#architecture">架构与写作引用</a><a href="#samples">逐文件结果</a><a href="#limits">边界与后续</a></nav>
<section id="results"><h2>验证覆盖了哪些实际行为</h2><p class="intro">30 份核心样本来自当前目录 65 份 PDF，按内容哈希去重后有 64 份；所选副本约 291 MiB，包含 6 份中文文献、211 页长文档和约 46 MiB 的大文件。另从副本制作已有标注、旋转裁剪、纯图像扫描、密码保护及截断损坏样本。</p><div class="checklist">
<article class="check"><span class="pass">通过</span><strong>真实 PDF 阅读</strong><p>30 份论文首、中、末页共 90 页完成渲染。三类正向派生样本另覆盖 8 页，包含旋转和非零裁剪框。</p></article>
<article class="check"><span class="pass">通过</span><strong>原生工具与标注保存</strong><p>真实鼠标创建高亮、下划线，在原生编辑框输入中文及 α、β；批量样本通过阅读器原生标注模型触发保存，并回读数据库。</p></article>
<article class="check"><span class="pass">通过</span><strong>完整进程重启恢复</strong><p>关闭服务及浏览器进程，开启全新会话。33 份文档共 101 条新标注、修订号和阅读位置恢复一致。</p></article>
<article class="check"><span class="pass">通过</span><strong>独立导出一致性</strong><p>pypdf 检查标注类型、页码、坐标、颜色与中文内容；PDFium 检查 98 页，Poppler 检查 33 个首页。隐藏标注后的底图像素均一致。</p></article>
<article class="check"><span class="pass">通过</span><strong>失败处理与重试</strong><p>模拟保存服务返回 503：显示未保存，草稿保留；点击重试后仅提交一次。另有 12 项事务、冲突、异常退出和源文件测试通过。</p></article>
<article class="check"><span class="pass">通过</span><strong>原件保护与版本校验</strong><p>65 份原始 PDF 前后 SHA-256 完全一致。管理副本被替换后，打开及导出会拒绝使用旧版本标注。</p></article>
</div><div class="flow" aria-label="本轮验证流程"><div>打开副本<small>Zotero Reader</small></div><b>→</b><div>创建标注<small>原生工具与模型</small></div><b>→</b><div>确认落盘<small>SQLite 事务</small></div><b>→</b><div>重启恢复<small>新进程 / 新会话</small></div><b>→</b><div>生成新 PDF<small>固定修订快照</small></div><b>→</b><div>外部核验<small>独立引擎 + Edge</small></div></div><div class="note">批量标注使用受控坐标和明确的测试文本，用于验证数据与几何的一致性；真实鼠标选字与中文批注另有独立操作样例。页面检查采用抽样，并未逐页人工审查全部 695 页。</div></section>
<section id="evidence"><h2>这次是真实组件和真实论文副本</h2><p class="intro">下面两张截图分别来自本地验证台和 Edge 自带 PDF 阅读器。它们不是概念界面，也不是上一次报告中的虚构文献演示。</p><figure class="proof"><img src="@@APP_IMAGE@@" alt="本地验证台实际打开论文副本，显示原生高亮、下划线与中文批注"><figcaption>本地验证台：阅读器、独立标注列表、保存状态和导出入口已连通。当前文献元数据仍是待校正状态。</figcaption></figure><figure class="proof"><img src="@@EDGE_IMAGE@@" alt="导出的 PDF 在 Edge 自带阅读器中打开，中文批注及希腊字母正常显示"><figcaption>Edge 原生阅读器：高亮、下划线、批注图标和中文弹窗均可见。测试批注“保存、重启、导出。中文与希腊字母 α β”在外部仍保持正确。</figcaption></figure><p class="small" style="margin-top:18px">独立校验环境：@@ENGINES@@。原生界面检查使用当前电脑安装的 Microsoft Edge；本次未宣称完成所有 Acrobat、福昕或移动端交互兼容测试。</p></section>
<section id="fixes"><h2>验证中发现的问题，已落实到代码</h2><div class="fixes"><article class="fix"><div><h3>画面已出现，宿主却一直等待初始化</h3><p>当前固定提交的 Reader 顶层初始化 Promise 没有完成。适配器改用实际 PDF 主视图的就绪信号，并加入明确超时。内部接口访问集中在一个文件，升级时需回归。</p></div></article><article class="fix"><div><h3>快速切换文献时，部分阅读位置没有落盘</h3><p>首次重启测试中，标注已全部恢复，但 7 份样本缺失阅读位置。改为直接捕获视图位置事件、串行保存，并在切换前捕获当前状态。随后重做完整进程重启，30 / 30 通过。</p></div></article><article class="fix"><div><h3>内嵌标注留在文件里，却没有显示在独立阅读器中</h3><p>新增独立的源 PDF 读取适配，将标准高亮与中文批注作为只读覆盖层显示。导出只写入应用新建的标注，原有内容继续保留，避免重复叠加。</p></div></article><article class="fix"><div><h3>图像与色彩解码需要 WebAssembly</h3><p>初次策略阻止了部分解码模块，已限定开放本地 WebAssembly 执行，并保持脚本与网络资源来自本机。修复后完成页面回归与独立像素比对。</p></div></article><article class="fix"><div><h3>不能把“高亮已经出现在屏幕上”当作保存成功</h3><p>上游保存存在延迟窗口。适配器即时提交，客户端保留有顺序的待提交草稿；数据库事务确认后才显示“已落盘”。故障注入验证了失败提示、草稿保留和幂等重试。</p></div></article></div></section>
<section id="architecture"><h2>给下一版留出边界，而非堆一个大文件</h2><p class="intro">应用实现按数据、用例、存储、阅读器与传输分开。未来增加界面或写作工具连接器时，核心文献与标注数据无需随之重新设计。</p><div class="grid"><article class="card"><h3>本轮已经实现的分离</h3><ul><li>文献、附件和标注各有稳定 ID；文件名、路径和引文编号都不作为主键。</li><li>SQLite 保存带版本的数据，事务保证批量修改原子性，旧修订写入会被拒绝。</li><li>Zotero 私有接口集中在前后端适配器，源码固定到具体提交。</li><li>导出放在后台 worker，绑定确定修订；原件与导出文件分开。</li></ul></article><article class="card"><h3>保持工程规模可控</h3><ul><li>使用单机模块化工程，尚未引入微服务、动态插件市场或 AI 系统。</li><li>资料库位置、端口与测试工具路径可配置。</li><li>个人 PDF、数据库和生成文件已排除出版本控制范围。</li><li>提供重复验证脚本、锁定版本、许可证和维护说明。</li></ul></article></div><h3 style="margin:28px 0 16px">未来 EndNote 类功能的接入方式</h3><div class="architecture"><div><span class="pill">数据基础已建立</span><h3>结构化文献信息</h3><p>稳定 itemId + CSL-JSON 方向的数据。作者、年份、期刊保持独立字段；未知信息不编造。</p></div><div><span class="pill">接口已定义 / 未实现</span><h3>引用格式处理器</h3><p>CitationFormatter 接入成熟 CSL 处理器，负责样式、引用簇、页码、编号刷新与参考文献表。</p></div><div><span class="pill">接口已定义 / 未实现</span><h3>写作工具连接器</h3><p>WritingConnector 连接以后确定的 Word、WPS 等工具，维护可更新的文档引用标记。</p></div></div><p class="small" style="margin-top:17px">“已经预留接口”不代表插件已经开发。文档中的引用簇 ID 与显示编号分离，为一处引用多篇文献、增删后的重排和样式切换留出空间。</p><div class="code-tree" style="margin-top:22px">src/domain → 数据与接口约定<br>src/application → 版本保护、源 PDF 读取、导出用例<br>src/storage → SQLite 与迁移脚本<br>src/adapters/zotero + src/web/zotero-reader-adapter.js → 上游耦合边界<br>src/server + src/web → 当前本机传输与验证界面</div><div class="links"><a href="../../ARCHITECTURE.md">查看架构决策与引用功能设计 ↗</a><a href="../../src/domain/contracts.d.ts">查看数据与扩展接口 ↗</a><a href="../../sources.lock.json">查看固定组件版本 ↗</a><a href="../../README.md">查看启动、复现与维护说明 ↗</a></div></section>
<section id="samples"><h2>逐文件结果与可打开的导出</h2><p class="intro">核心样本与正向派生样本分别保留记录。每份导出都对应固定修订快照；之后在验证台继续编辑，不会改写这里的历史导出。</p><div class="table-tools"><span class="small">33 份导出 · 101 条新标注 · 原有内嵌标注保持</span><input id="filter" type="search" placeholder="筛选文件名或 sample 编号…" aria-label="筛选验证文件"></div><div class="table-wrap"><table><thead><tr><th>样本</th><th>原文件 / 派生样本名称</th><th>页数</th><th>新标注</th><th>恢复与导出</th><th>导出文件</th></tr></thead><tbody>@@ROWS@@</tbody></table></div><p class="small" style="margin-top:12px">正文与截图全部内嵌，可离线查看。导出文件和工程链接是相对路径，使用时请保留整个工程目录结构。</p></section>
<section id="limits"><h2>哪些能力还不能当作已经完成</h2><div class="grid"><article class="card"><span class="pill">明确限制</span><h3>阅读与兼容性</h3><p>密码 PDF 会明确提示需要密码，本阶段尚未实现解锁与加密导出。扫描页支持查看、区域标记和批注，文字检索需要后续 OCR。</p><p>已有内嵌标注只读；手写、文本框、跨页高亮和改页顺序没有纳入本轮完整验收。</p></article><article class="card"><span class="pill">开发范围</span><h3>技术验证台，尚非最终安装版</h3><p>当前使用本机浏览器与本地服务。最终 Electron 包装、中文工具栏、完整分类检索、元数据校正和 Word/WPS 插件需要后续开发。</p><p>在未显示“已落盘”时，强制终止、断电或清空浏览器资料不承诺零丢失。</p></article></div><div class="note">少数源文件仍产生交叉引用、字体表或内部跳转目标警告。最终抽样阅读和独立底图校验通过，但这不等于每个内部链接或每一页均已人工确认。</div><h3 style="margin:28px 0 12px">建议下一步</h3><p class="intro">进入第二阶段：确定正式文献库界面和数据编辑流程，落实作者、年份、期刊规范化及组合检索；沿用已验证的保存、导出和恢复模块。写作引用能力按独立接口接入，避免绑定阅读器实现。</p><details open><summary>怎样启动这份可运行的验证工程？</summary><p>在工程根目录双击“启动验证台.cmd”，默认打开 http://127.0.0.1:4178。使用完毕双击“停止验证台.cmd”。当前电脑已有经过验证的 Node 运行时；无需重新安装依赖即可运行现成构建。备份前先停止服务，再复制 data/workspace。</p></details><details><summary>怎么复查本轮结论？</summary><p>运行 npm test 可重做 12 项基础测试；浏览器回归函数和独立导出脚本位于 scripts。批量标注测试会写入测试数据，重跑时建议另设 PAPER_WORKBENCH_DATA。以下机器可读记录均来自实际执行结果。</p></details><div class="links"><a href="../phase-1-summary.json">验证结论汇总 JSON ↗</a><a href="../ui-batch-results.json">30 份样本的原始流程结果 ↗</a><a href="../ui-recovery-final.json">核心样本重启恢复结果 ↗</a><a href="../independent-export-checks.json">独立结构与渲染比对结果 ↗</a><a href="../source-integrity.json">原始文件完整性核对 ↗</a><a href="../all-tests-final.log">12 项基础测试日志 ↗</a></div></section>
<footer class="foot"><strong>本地文献工作台 · 第一阶段完成</strong><br>验证日期：2026 年 10 月 30 日（Asia/Shanghai）。组件来源：<a href="https://github.com/zotero/reader">Zotero Reader</a>、<a href="https://github.com/zotero/document-worker">Document Worker</a>、<a href="https://github.com/mozilla/pdf.js">PDF.js</a>。未来引用设计参考 <a href="https://docs.citationstyles.org/en/master/primer.html">CSL</a> 与 <a href="https://learn.microsoft.com/en-us/office/dev/add-ins/word/">Word Add-ins</a>。本轮未公开发布软件或上传论文。</footer>
</main><script>document.getElementById('print').addEventListener('click',()=>window.print());document.getElementById('filter').addEventListener('input',event=>{const q=event.target.value.toLowerCase();document.querySelectorAll('tbody tr').forEach(row=>row.hidden=!row.dataset.name.toLowerCase().includes(q));});window.addEventListener('beforeprint',()=>{document.querySelectorAll('details').forEach(x=>x.open=true);document.querySelectorAll('tbody tr').forEach(x=>x.hidden=false);});</script></body></html>'''
template=template.replace('@@APP_IMAGE@@',image('playwright/workbench-final.png')).replace('@@EDGE_IMAGE@@',image('playwright/edge-export-comment.png')).replace('@@ROWS@@',''.join(rows)).replace('@@ENGINES@@',esc(', '.join(f'{key} {value}' for key,value in engine.items())))
destination=report/'第一阶段技术验证结果.html'
destination.write_text(template,encoding='utf-8')
print(json.dumps({'report':str(destination),'bytes':destination.stat().st_size,'summary':summary},ensure_ascii=False))
